// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(address actor, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(actor != address(0));
        depositAmount = bound(depositAmount, 1, 1 ether);
        withdrawAmount = bound(withdrawAmount, 0, depositAmount);

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        vm.prank(actor);
        bool ok1;
        try c.withdraw(withdrawAmount) {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        vm.assume(ok1);

        uint256 rem = depositAmount - withdrawAmount;
        vm.prank(actor);
        bool ok2;
        try c.withdraw(rem) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(ok2);
    }
}
